templates.code:
name: "{pipeline}"
platform: "ensemble"
max_batch_size: {n}
input [ { name: "IMAGE", data_type: TYPE_UINT8, dims: [ -1 ] } ]     # los bytes del JPEG
output [ { name: "LOGITS", data_type: TYPE_FP32, dims: [ {clases} ] } ]
ensemble_scheduling {
  step [
    { model_name: "{preproceso}"
      model_version: -1
      input_map { key: "RAW" value: "IMAGE" }
      output_map { key: "TENSOR" value: "preprocessed" } },
    { model_name: "{modelo}"
      model_version: -1
      input_map { key: "input" value: "preprocessed" }
      output_map { key: "logits" value: "LOGITS" } }
  ]
}
